import numpy as np
def epsilon_greedy(Q, state, epsilon):
    if np.random.random() < epsilon:
        return np.random.randint(Q.shape[1])
    return int(np.argmax(Q[state]))
def q_update(Q, s, a, r, s_next, alpha=0.1, gamma=0.9):
    Q[s,a] += alpha * (r + gamma * np.max(Q[s_next]) - Q[s,a])
def q_learning(env, episodes=100, alpha=0.1, gamma=0.9, epsilon=0.1):
    Q = np.zeros((env['n_states'], env['n_actions']))
    rewards = []
    for _ in range(episodes):
        s = 0; total = 0
        for _ in range(50):
            a = epsilon_greedy(Q, s, epsilon)
            s_next = int(np.random.choice(env['n_states'], p=env['trans'][s][a]))
            r = env['rewards'][s][a][s_next]
            q_update(Q, s, a, r, s_next, alpha, gamma)
            s = s_next; total += r
        rewards.append(total)
    return {'Q': Q, 'avg_return': round(sum(rewards[-20:])/20, 2)}

