import numpy as np
class ReplayBuffer:
    def __init__(self, cap): self.buf=[];self.cap=cap;self.pos=0
    def push(self, s, a, r, s2, d):
        if len(self.buf)<self.cap: self.buf.append((s,a,r,s2,d))
        else: self.buf[self.pos]=(s,a,r,s2,d)
        self.pos=(self.pos+1)%self.cap
    def sample(self,n):
        idx=np.random.choice(len(self.buf),n)
        return [self.buf[i] for i in idx]
def compute_td_loss(batch, online, target, gamma=0.9):
    loss = 0
    for s, a, r, s2, d in batch:
        q_target = r if d else r + gamma * np.max(target[s2])
        q_current = online[s][a]
        loss += (q_current - q_target) ** 2
    return loss / len(batch)

import numpy as np
def compute_advantages(rewards, values, gamma=0.99, lam=0.95):
    advantages = []
    gae = 0
    for t in reversed(range(len(rewards))):
        delta = rewards[t] + gamma * (values[t+1] if t+1<len(values) else 0) - values[t]
        gae = delta + gamma * lam * gae
        advantages.insert(0, gae)
    return np.array(advantages, dtype=float)
def ppo_clip_surrogate(old_logp, new_logp, adv, eps=0.2):
    ratio = np.exp(new_logp - old_logp)
    clipped = np.clip(ratio, 1-eps, 1+eps)
    return -min(ratio * adv, clipped * adv)

import numpy as np
def bellman_expectation(V,P,R,gamma=0.9):
    n=len(V);newV=np.zeros(n)
    for s in range(n):
        q_vals=[]
        for a in range(len(P[s])):
            q=sum(P[s][a][s2]*(R[s][a][s2]+gamma*V[s2])for s2 in range(n))
            q_vals.append(q)
        newV[s]=np.mean(q_vals)
    return newV
def bellman_optimal(V,P,R,gamma=0.9):
    n=len(V);newV=np.zeros(n)
    for s in range(n):
        q_vals=[]
        for a in range(len(P[s])):
            q=sum(P[s][a][s2]*(R[s][a][s2]+gamma*V[s2])for s2 in range(n))
            q_vals.append(q)
        newV[s]=max(q_vals)
    return newV

import numpy as np
def double_dqn_update(online,target,batch,gamma=0.9):
    loss=0
    for s,a,r,s2,d in batch:
        best_a=int(np.argmax(online[s2]))
        q_target=r if d else r+gamma*target[s2][best_a]
        loss+=(online[s][a]-q_target)**2
    return loss/len(batch)

